Lemma ram_brk_node_at (pc : Z) :
  (pc = 0x1e3d8 \/ pc = 0x1e414)%Z -> forall cur req, req <> 0%Z ->
  impl psegs (at_node psegs) (enode (NBrk req) (dec_brk cur req))
       (epost (fun a ms' => ms' = MS (rbrk_regs (Z_to_bv 64 (brk_res cur req a))) F (Z_to_bv 64 (pc + 4)) fc None (brk_mem m cur req a) (seg_rom psegs)))
       (MS (rbrk_regs (Z_to_bv 64 req)) F (Z_to_bv 64 pc) fc None m (seg_rom psegs)).
